import sys

ROOT = '/home/user/fortress/'


class Doc:
    def __init__(self, path):
        self.path = ROOT + path if not path.startswith('/') else path
        self.text = open(self.path, encoding='utf-8').read()
        self.orig = self.text

    def rep(self, old, new, count=1):
        n = self.text.count(old)
        if n != count:
            sys.exit(f'{self.path}: expected {count} of {old[:90]!r}, found {n}')
        self.text = self.text.replace(old, new)
        return self

    def after(self, anchor, new, count=1):
        return self.rep(anchor, anchor + new, count)

    def save(self):
        if self.text != self.orig:
            open(self.path, 'w', encoding='utf-8').write(self.text)
            print('saved', self.path)
        else:
            print('unchanged', self.path)

